package main

import "fmt"

func main() {
	a := [3][4]int{{3, -2, 5, 1}, {-4, 7, 0, 6}, {2, 9, -8, -3}}
	b := [4][2]int{{1, 4}, {-5, 2}, {6, -1}, {0, 7}}
	for i := 0; i < 3; i++ {
		row := [2]int{}
		for j := 0; j < 2; j++ {
			sum := 0
			for k := 0; k < 4; k++ {
				sum += a[i][k] * b[k][j]
			}
			row[j] = sum
		}
		for _, value := range row {
			fmt.Printf("%5d", value)
		}
		fmt.Println()
	}
}
